<?php $posts=records('posts');$activeCategories=array_values(array_unique(array_column($posts,'category')));$categories=array_values(array_filter(array_column(records('blog_categories'),'title'),fn($category)=>in_array($category,$activeCategories,true)));$selected=is_string($_GET['category']??null)&&in_array($_GET['category'],$categories,true)?$_GET['category']:'All';usort($posts,fn($a,$b)=>strcmp($b['date']??'',$a['date']??''));$visibleCount=count(array_filter($posts,fn($p)=>$selected==='All'||$p['category']===$selected));?>
<div class="container">
<section class="blog-page-hero" aria-labelledby="blog-hero-title"><header class="page-heading blog-page-heading"><span class="eyebrow">INSIGHTS & FIELD NOTES</span><h1 id="blog-hero-title">Better questions.<br><span class="muted-heading">Better software decisions.</span></h1><p>Practical thinking on custom software, SaaS and the systems that help a business work better.</p></header></section>
<section class="listing-section blog-listing" aria-label="Articles"><div class="blog-listing-head"><div><span class="eyebrow">EXPLORE TOPICS</span><h2>Ideas for better software.</h2></div><p class="result-status" data-filter-status aria-live="polite"><?=$visibleCount?$visibleCount.' articles':'No articles in this category yet. Explore another category.'?></p></div><form class="filters blog-filters" method="get" data-filter-form><?php foreach(array_merge(['All'],$categories) as $cat):?><button class="filter <?=$selected===$cat?'selected':''?>" type="submit" name="category" value="<?=e($cat)?>" data-filter="<?=e($cat)?>" aria-pressed="<?=$selected===$cat?'true':'false'?>"><?=e($cat)?></button><?php endforeach;?></form><div class="blog-grid"><?php foreach($posts as $post)require __DIR__.'/../partials/blog-card.php';?></div></section></div><?php cta('Ready to put an idea<br>into practice?');?>
